parameters.jsCode:
const d = $input.first().json.body;

const UMBRALES = { cpu: 80, ram: 85, swap: 70, temp: 80 };

const alertas = [];

if (d.mediaCPU > UMBRALES.cpu)
  alertas.push(`CPU media al ${d.mediaCPU}% (umbral ${UMBRALES.cpu}%)`);

if (d.mediaRAM > UMBRALES.ram)
  alertas.push(`RAM media al ${d.mediaRAM}% (umbral ${UMBRALES.ram}%)`);

if (d.SwapPorcentaje > UMBRALES.swap)
  alertas.push(`SWAP al ${d.SwapPorcentaje}% (umbral ${UMBRALES.swap}%)`);

if (d.temperatura !== null && d.temperatura > UMBRALES.temp)
  alertas.push(`Temperatura a ${d.temperatura} °C (umbral ${UMBRALES.temp} °C)`);

return [{ json: { ...d, alertas, hayAlertas: alertas.length > 0 } }];
